#include "BodyLoads.h"
#include <cmath>
#include <cstdio>
#include <limits>
int main(){int failed=0;auto check=[&](bool ok,const char*name){if(!ok){std::printf("FAIL %s\n",name);++failed;}};bodyloads::State s;auto load=s.Sample({0,0,0},.02f,false);check(load.z==-20,"parked material carries weight");load=s.Sample({0,0,-.4f},.02f,false);check(std::fabs(load.z)<1e-5f,"clean native freefall has zero apparent weight");load=s.Sample({100,0,-.4f},.02f,true);check(std::fabs(load.x)+std::fabs(load.z)<1e-5f,"already spent contact impulse is not charged as section load");load=s.Sample({100,0,-.8f},.02f,false);check(std::fabs(load.x)+std::fabs(load.z)<1e-5f,"next freefall interval does not replay held shock");load=s.Sample({100,0,-.8f},.02f,false);check(load.z==-20,"resting support restores weight after shock");load=s.Sample({1e6f,0,0},.02f,false);check(std::sqrt(load.x*load.x+load.y*load.y+load.z*load.z)<=1000.001f,"finite native load sampling has explicit acceleration cap");auto before=load;load=s.Sample({std::numeric_limits<float>::quiet_NaN(),0,0},.02f,false);check(load.x==before.x&&load.z==before.z,"invalid native sample preserves last clean load");if(!failed)std::puts("Native body apparent load cases pass");return failed?1:0;}
